import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPUTWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "ViewSubProgram.js";

class ViewSubProgram extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            subProgram: null,
            programs: [],
            error: null,
            isEditing: false,
            editName: '',
            editDescription: '',
            editProgramId: '',
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
            parentProgram: null,
            parentProgramLoading: false,
        };
    }

    componentDidMount() {
        document.title = "View Sub-Program";
        this.fetchPrograms();
        this.fetchSubProgram();
    }

    fetchPrograms() {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list';
        const reqData = { page: 1, size: 100 };

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => response.status === 200 ? response.json() : null)
        .then(result => {
            if (result && result.data) {
                this.setState({ programs: result.data.content || [] });
            }
        })
        .catch(error => Logger(FILE_NAME, "fetchPrograms", "ERROR", "error", error));
    }

    fetchSubProgram() {
        const subProgramId = this.props.match.params.subProgramId;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/' + subProgramId;

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchSubProgram", "SUCCESS", "result", result);
            this.setState({ isLoaded: true, subProgram: result.data });
            if (result.data && result.data.programId) {
                this.fetchParentProgram(result.data.programId);
            }
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchSubProgram", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    getProgramName = (programId) => {
        const prog = this.state.programs.find(p => p.id === programId);
        return prog ? prog.name : programId;
    }

    fetchParentProgram(programId) {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/program/' + programId;

        this.setState({ parentProgramLoading: true });

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchParentProgram", "SUCCESS", "result", result);
            this.setState({ parentProgramLoading: false, parentProgram: result.data });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchParentProgram", "ERROR", "error", error);
            this.setState({ parentProgramLoading: false });
        });
    }

    startEditing = () => {
        const { subProgram } = this.state;
        this.setState({
            isEditing: true,
            editName: subProgram.name,
            editDescription: subProgram.description || '',
            editProgramId: String(subProgram.programId),
        });
    }

    cancelEditing = () => {
        this.setState({ isEditing: false });
    }

    saveChanges = () => {
        const { subProgram, editName, editDescription, editProgramId } = this.state;
        const payload = { name: editName, description: editDescription || null, programId: Number(editProgramId) };

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/' + subProgram.id;

        fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "saveChanges", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1, subProgram: result.data, isEditing: false });
            setTimeout(() => this.setState({ loadingModalVisible: false, loadingModalState: 0 }), 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "saveChanges", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    render() {
        const { isLoaded, error, isEditing } = this.state;

        if (!isLoaded) return <Loading />;

        if (error) {
            return (
                <div style={{ textAlign: 'center', padding: '40px', color: '#dc3545' }}>
                    <h3>Error loading sub-program</h3>
                    <p>{error}</p>
                    <a href="#/sub-programs">← Back</a>
                </div>
            );
        }

        return (
            <div>
                <a href="#/sub-programs" style={{ textDecoration: 'none' }}>
                    <CButton color="secondary" className="mb-3">← Back to Sub-Programs List</CButton>
                </a>
                <CContainer>
                    <CRow className="justify-content-center">
                        <CCol md="6">
                            <CCard className="p-4">
                                <CCardBody>
                                    {!isEditing ? this.renderViewMode() : this.renderEditMode()}
                                </CCardBody>
                            </CCard>
                        </CCol>
                    </CRow>
                </CContainer>
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderViewMode() {
        const { subProgram } = this.state;

        return (
            <>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h1>📦 {subProgram.name}</h1>
                    <CButton color="primary" onClick={this.startEditing}>✏️ Edit</CButton>
                </div>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <h5>📝 Description</h5>
                    <p>{subProgram.description || 'No description'}</p>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <h5>🏗️ Parent Program {subProgram.programId && (
                        <span style={{ fontSize: '0.8em', color: '#6c757d' }}>
                            (<a href={'#/program/' + subProgram.programId} target="_blank" rel="noopener noreferrer">#{subProgram.programId}</a>)
                        </span>
                    )}</h5>
                    {this.renderParentProgram()}
                </div>
                <div style={{ display: 'flex', gap: '24px', marginBottom: '12px' }}>
                    <div>
                        <h5>🕐 Created</h5>
                        <p>{subProgram.createdOn ? new Date(subProgram.createdOn).toLocaleString() : '—'}</p>
                    </div>
                    <div>
                        <h5>🔄 Last Updated</h5>
                        <p>{subProgram.updatedOn ? new Date(subProgram.updatedOn).toLocaleString() : '—'}</p>
                    </div>
                </div>
            </>
        );
    }

    renderParentProgram() {
        const { parentProgram, parentProgramLoading } = this.state;

        if (parentProgramLoading) {
            return <p>Loading parent program...</p>;
        }

        if (!parentProgram) {
            return <p style={{ color: '#6c757d', fontStyle: 'italic' }}>Unable to load parent program details.</p>;
        }

        return (
            <div style={{ backgroundColor: '#f8f9fa', border: '1px solid #dee2e6', borderRadius: '6px', padding: '12px' }}>
                <div style={{ marginBottom: '8px' }}>
                    <strong>Name:</strong>{' '}
                    <a href={'#/program/' + parentProgram.id} target="_blank" rel="noopener noreferrer">
                        {parentProgram.name}
                    </a>
                </div>
                <div style={{ marginBottom: '8px' }}>
                    <strong>Description:</strong> {parentProgram.description || 'No description'}
                </div>
                <div style={{ marginBottom: '8px' }}>
                    <strong>Type:</strong>{' '}
                    <span style={{
                        padding: '2px 8px',
                        borderRadius: '4px',
                        backgroundColor: parentProgram.type === 'WORK' ? '#e3f2fd' : '#fce4ec',
                        color: parentProgram.type === 'WORK' ? '#1565c0' : '#c62828',
                        fontWeight: 'bold',
                        fontSize: '0.85em',
                    }}>
                        {parentProgram.type}
                    </span>
                </div>
                <div>
                    <strong>Created:</strong> {parentProgram.createdOn ? new Date(parentProgram.createdOn).toLocaleString() : '—'}
                </div>
            </div>
        );
    }

    renderEditMode() {
        const { editName, editDescription, editProgramId, programs } = this.state;

        return (
            <>
                <h2>✏️ Edit Sub-Program</h2>
                <hr />
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Program *</strong></label>
                    <select
                        value={editProgramId}
                        onChange={(e) => this.setState({ editProgramId: e.target.value })}
                        required
                        style={{ display: 'block', width: '100%', padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px' }}
                    >
                        <option value="">Select a program</option>
                        {programs.map(p => (
                            <option key={p.id} value={p.id}>{p.name} ({p.type})</option>
                        ))}
                    </select>
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Name *</strong></label>
                    <CInput
                        value={editName}
                        onChange={(e) => this.setState({ editName: e.target.value })}
                        required
                    />
                </div>
                <div style={{ marginBottom: '12px' }}>
                    <label><strong>Description</strong></label>
                    <textarea
                        value={editDescription}
                        placeholder="Description (optional)"
                        onChange={(e) => this.setState({ editDescription: e.target.value })}
                        rows="3"
                        style={{ display: 'block', width: '100%', padding: '6px 12px', border: '1px solid #d8dbe0', borderRadius: '4px', resize: 'vertical' }}
                    />
                </div>
                <hr />
                <div style={{ display: 'flex', gap: '12px' }}>
                    <CButton color="success" onClick={this.saveChanges}>💾 Save</CButton>
                    <CButton color="secondary" onClick={this.cancelEditing}>Cancel</CButton>
                </div>
            </>
        );
    }
}

export default ViewSubProgram;
